  (* [comment removed for export] *)
  Lemma new_block_outside : forall s' L m' p A n LB SP a,
    as_RHEAP H s' L m' -> In (p, A, n) L -> (forall b, In b LB -> In b L) -> (forall b, In b LB -> blk_id b <> p) ->
    aceil <= SP -> aclient_addr H LB SP a -> a + 1 <= A \/ A + n <= a.
  Proof.
    intros s' L m' p A n LB SP a HP IN SUB NEW CE HC.
    eapply new_block_disjoint_client; [exact HP| exact IN| exact SUB| exact NEW| apply aclient_addr_range; exact HC| exact CE| lia].
  Qed.

  Lemma new_block_vs_aobj : forall s' L m' p A n LB LF m1 O k,
    as_RHEAP H s' L m' -> In (p, A, n) L -> (forall b, In b LB -> In b L) -> (forall b, In b LB -> blk_id b <> p) ->
    as_RFS H LF m1 -> aobj LB LF O k -> 0 < k -> O + k <= A \/ A + n <= O.
  Proof.
    intros s' L m' p A n LB LF m1 O k HP IN SUB NEW RF AO Hk.
    eapply new_block_disjoint_client; [exact HP| exact IN| exact SUB| exact NEW| eapply (aobj_aclient_range H HH LF LB m1 aceil); [exact RF| exact AO]| lia| exact Hk].
  Qed.

